class selenium_megazone(object):
    """
    Keywords for megazone


    ..note:: selenium_megazone lib requires display drivers to be installed
    at the machine on which tests are run. If one needs run tests without
    display options should install xvfb tool at the machine.
    """

    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    ROBOT_LISTENER_API_VERSION = 2

    def __init__(self):
        self.page = None
        self.__driver = None
        self._download_dir = None
        self._tmp_download_dir = False
        self._url = None
        self._username = None
        self._password = None
        self._display = None
        self.__debug_dir = None
        self.downloader = Downloader()

    @property
    def download_dir(self):
        """ Get download directory path.
        If path was not provided, function returns path to temporary directory,
        which will be removed during logout. """
        return self.get_download_dir()

    def get_download_dir(self):
        """ Function for compatibility with robot framework.  See download_dir property. """
        if self._download_dir is None:
            self._download_dir = tempfile.mkdtemp(suffix="ta-selenium-megazone")
            self._tmp_download_dir = True
        return self._download_dir

    @download_dir.setter
    def download_dir(self, download_dir):
        """ Set download directory path.
        Note that this function can be called only before driver initialization.

        :param download_dir: path to download dir
        """
        self.set_download_dir(download_dir)

    def set_download_dir(self, download_dir):
        """ Function for compatibility with robot framework. See download_dir property. """
        if self.__driver is None:
            self._download_dir = download_dir
        else:
            raise AttributeError("Download dir must be set before initialization of "
                                 "driver (in most cases before login keyword)")

    @property
    def _debug_dir(self):
        return self.get_debug_dir()

    def get_debug_dir(self):
        """
        Get debug directory path.
        """
        if self.__debug_dir is None:
            self.__debug_dir = tempfile.mkdtemp(prefix="taf_selenium_megazone_debug")
        return self.__debug_dir

    @_debug_dir.setter
    def _debug_dir(self, download_dir):
        self.set_download_dir(download_dir)

    def set_debug_dir(self, debug_dir):
        """
        Set debug directory path.
        :param debug_dir: path to download dir
        """
        self.__debug_dir = os.path.join(debug_dir, "taf_selenium_megazone_debug")
        if not os.path.exists(self.__debug_dir):
            os.makedirs(self.__debug_dir)

    @property
    def _driver(self):
        if self.__driver is None:
            self.__driver = CustomWebdriver(self.download_dir)
        return self.__driver

    def save_screenshot(self, filename, screenshot_dir=None):
        """
        Keyword for save screenshot, tester can add this keyword after failed test case to provide clues for developer
        :param filename: str, png file name, please keep it unique
        :param screenshot_dir: str or None, screenshot path, user should have permission to read and write this dir
        """
        screenshot_dir = screenshot_dir if screenshot_dir else self._debug_dir
        Debug(self._driver, screenshot_dir).save_screenshot(filename)

    def enable_virtual_display(self, width=1920, height=1280):
        """
        This keyword is used to enable virtual display - with it enabled browser
        window will not be displayed on screen.

        In order for this functionality to work correctly this keyword must to be
        called before `Login` keyword is called (which would spawn browser window).

        Please make sure "xvfb" service is installed on the environment.

        :param width: int, width of browser
        :param height: int, height of browser
        """
        self._display = Display(visible=0, size=(width, height))
        self._display.start()

    def disable_virtual_display(self):
        """
        This keyword is used to disable virtual display.
        Please make sure to call this method at the end of test if you've call "enable_virtual_display"
        """
        self._display.stop()

    @catch_interface_exception
    def login(self, url, username, password, after_reset=False):
        """
        Login into megazone bts.
        :param url: url to megazone management system
        :param username: username
        :param password: password
        :param after_reset: allow login to fail. New vesions of software performs login automatically.
        """
        url = format_ip_address_if_ipv6(url)
        self._driver.get(url)
        self._url = url
        self._username = username
        self._password = password
        self.page = LoginPage(self._driver)
        self.page = self.page.login(username, password, after_reset)

