    def get_vm_info(self, name):
        """
        Returns hostname, ip address and status about vm.

        :param name: virtual machine names
        :return: List with described elements
        """
        return [self.get_vm_hostname(name),
                self.get_vm_ip_address(name),
                self.get_vm_status(name)]

