    @catch_interface_exception
    def logout(self):
        """
        Closes browser and remove contents of download dir if download dir path was not provided.
        """
        if self._tmp_download_dir:
            shutil.rmtree(self.download_dir)
            self._tmp_download_dir = False
            self._download_dir = None
        self.page.logout()
        self.close_browser()

    @catch_interface_exception
    def close_browser(self):
        """
        Closes browser in any case.
        """
        self._driver.close()
        self.__driver = None

    @catch_interface_exception
    def close_browser_if_logout_is_not_possible(self):
        """
        Check if logout from WebUI is possible, if not, close the browser.
        """
        if not self.page.check_if_logout_possible():
            self.close_browser()

    @catch_interface_exception
    def reset_cloud(self, url, login, password, show_timeout=120, disappear_timeout=300):
        """Keyword reset cloud using megazone site manager

        :param url: str
        :param login: str
        :param password: str
        :param show_timeout: int timeout for apperance of bts connecting modal
        :param disappear_timeout: int timeout for disapperance of bts connecting modal
        """
        with CustomWebdriver() as driver:
            login_page = LoginPage(driver)
            driver.get(url)
            self.page = login_page.login(login, password)
            self.click_reset_site(show_timeout, disappear_timeout)
            login_page = LoginPage(driver)
            login_page.login(login, password, after_reset=True)

    @catch_interface_exception
    def click_reset_site(self, show_timeout=120, disappear_timeout=300, expand_headers=None, reset_modal_show_timeout=60):
        """Keyword reset cloud using megazone site manager

        :param show_timeout: int timeout for apperance of bts connecting modal
        :param disappear_timeout: int timeout for disapperance of bts connecting modal
        :param expand_headers: list, names from cascading header, e.g ['BTS', 'RAP 1']
        :param reset_modal_show_timeout: timeout to wait for reset modal appear
        """
        self.page = self.page.click_site_management()
        expand_headers = expand_headers if expand_headers else []
        for header_name in expand_headers:
            self.page.expand_header(header_name)
        confirm_modal = self.page.click_reset_button(reset_modal_show_timeout)
        connection_lost_modal = confirm_modal.confirm()
        connection_lost_modal.wait_until_ends(int(show_timeout), int(disappear_timeout))

    @catch_interface_exception
    def save_snapshot(self, url=None, login=None, password=None, download_dir=None,
                      snapshot_prepare_timeout=600, prep_download_timeout=60):
        """Keyword saves snapshot from cloud using megazone site manager.

        :param url: str, obsolete, default None
        :param login: str, obsolete, default None
        :param password: str, obsolete, default None
        :param download_dir, obsolete, default None
        :param snapshot_prepare_timeout max time to create snapshot
        :param prep_download_timeout max time to start download after snapshot is created
        :return path to downloaded file
        """
        snapshot_prepare_timeout = int(snapshot_prepare_timeout)
        prep_download_timeout = int(prep_download_timeout)
        path = self.collect_snapshot(snapshot_prepare_timeout, prep_download_timeout)
        return path

    @catch_interface_exception
    def collect_snapshot(self, snapshot_prepare_timeout=600, prep_download_timeout=60):
        """Keyword saves snapshot from cloud using megazone site manager.

        :param snapshot_prepare_timeout max time to create snapshot
        :param prep_download_timeout max time to start download after snapshot is created
        :return path to downloaded file
        """
        self.page = self.page.click_snapshot()
        self.select_save_location('Local drive')
        return self.save_or_cancel_snapshot('Save', snapshot_prepare_timeout, prep_download_timeout)

