    @catch_interface_exception
    def select_save_location(self, location):
        """Keyword to select save location on snapshot sub page.

        :param location: str value of the selectd item as below:
        BTS only
        Local drive
        Server
        NMS
        """
        self.page = self.page.click_snapshot()
        select_id = {
            'BTS only': 'snapshot-save-sbts',
            'Local drive': 'snapshot-save-local',
            'Server': 'snapshot-save-server',
            'NMS': 'snapshot-save-nms'
        }
        self.page.select_snapshot_save_loation(select_id[location])

    @catch_interface_exception
    def save_or_cancel_snapshot(self, operation, first_stage_timeout=600, second_stage_timeout=60):
        """Keyword to save snapshot or cancel snapshot saving.

        :param operation: 'Save' or 'Cancel'
        :param first_stage_timeout: int timeout value to wait for saving or cancelling snapshot,
                                    default value 600s
        :param second_stage_timeout: int timeout value to wait for saving existing snapshot,
                                     default value 60s
        :return if the operation is 'Save' and save to local server selected,
                    return path to downloaded file if successfully saved
                if the operation is 'Save' and other save location selected,
                    return "snapshot download finished" if successfully saved
                if the operation is 'Cancel' and cancel successfully,
                    return "Snapshot cancelled: "Snapshot was cancelled by user""
                if timeout happend during the 'Save' or 'Cancel' operation, TimeoutException raised
                if there is a snapshot error with 'Save' or 'Cancel' operation, error text is returned
        """
        self.page = self.page.click_snapshot()
        if operation == 'Save':
            local_drive_xpath = "//*[@id='snapshot-save-local']"
            if self._driver.find_element_by_xpath(local_drive_xpath).is_selected():
                start_time = time.time()
                self.page.save_snapshot(first_stage_timeout, second_stage_timeout)
                return self.downloader.download(download_dir=self.download_dir,
                                                start_downloading_time=start_time)
            else:
                return self.page.save_snapshot(first_stage_timeout, second_stage_timeout)
        elif operation == 'Cancel':
            return self.page.cancel_snapshot(first_stage_timeout)
        else:
            raise AttributeError("Wrong Operation")

    @catch_interface_exception
    def wait_for_snapshot_status_update(self, start_timeout=10, end_timeout=10):
        """
        Waits for snapshot status update to be started and finished.
        :param start_timeout: time to wait (in seconds) for snapshot status update to start; defaults to 10 seconds
        :type start_timeout: int
        :param end_timeout: time to wait (in seconds) for snapshot status update to finish; defaults to 10 seconds
        :except TimeoutException: raised when snapshot status update was not started or was not finished
        """
        self.page = self.page.click_snapshot()
        self.page.wait_for_snapshot_status_update(start_timeout=start_timeout, end_timeout=end_timeout)

