    @catch_interface_exception
    def get_carrier_frequency(self, mode):
        """
        Get carrier frequency from Monitoring and Tests -> Conformance Test -> 5G Uplink/Downlink.
        Method raises FailedToGetValue exception if test dedicated state is disabled.
        Method raises ValueError exception if user provide mode else than 'uplink' or 'downlink'.
        You have to be in Test Dedicated State to run this keyword.
        :param mode: 'uplink' or 'downlink'
        :type mode: str
        :return: carrier frequency in MHz
        :rtype: float
        """
        state = self.check_if_dedicated_state_status_is_disabled()
        if state:
            raise FailedToGetValue(""" Can't get carrier frequency - Test dedicated state is disabled.
                                   Turn on test dedicated state and try again. """)
        return self.page.get_carrier_frequency(mode)

    @catch_interface_exception
    def select_conformance_test_mode(self, mode='downlink'):
        """
        Method clicks between '5G Downlink' or '5G Uplink' on
        Monitoring and Tests -> Conformance Test bar.
        Method raises FailedToGetValue exception if test dedicated state is disabled.
        Method raises ValueError exception if user provide mode other than 'uplink' or 'downlink'.
        You have to use setup_conformance_test_for_test_model to run this
        keyword(test dedicated state is necessary).
        :param mode: 'downlink' or 'uplink' to choose between modes on Conformance Test bar.
        :type mode: string
        """
        state = self.check_if_dedicated_state_status_is_disabled()
        if state:
            raise ElementIsNotReachable(""" Can't reach desired buttons - Test dedicated state is disabled.
                                   Turn on test dedicated state and try again. """)
        self.page.select_conformance_test_mode(mode)

    def disable_screen_lock(self, time_interval=30000):
        """
        Method to disable screen lock after idle for some minutes
        :param time_interval: event execution time interval, 30000 is 30s
        :type time_interval: int
        :return: None
        """
        mouse_move_event_script = 'window.interval_id = setInterval(function(){var event = new Event("mousemove"); ' \
                                  'document.body.dispatchEvent(event);}, %d)' % int(time_interval)
        self._driver.execute_script(mouse_move_event_script)

    def enable_screen_lock(self):
        """
        Method to enable screen lock after idle for some minutes
        """
        interval_id = self._driver.execute_script("return window.interval_id")
        self._driver.execute_script("clearInterval({})".format(interval_id))
